import{t as e}from"./jsx-runtime-lw2jiZar.js";import{D as t,M as n,N as r,O as i,P as a,S as o,_ as s,b as c,k as l,l as u,n as d,o as f,p,t as m}from"./shared-C5BCElVa.js";import{t as h}from"./CodeEditor-BZlrvoTL.js";var g=e(),_=[`# Короткое имя используем, только если проверка показывает Python 3.12:`,`python --version`,`python main.py`,``,`# Если python отсутствует или запускает не Python 3.12:`,`$pythonExe = "C:\\Users\\Student\\AppData\\Local\\Programs\\Python\\Python312\\python.exe"`,`& $pythonExe --version`,`& $pythonExe ".\\main.py"`].join(`
`);function v({module:e}){return(0,g.jsxs)(r,{children:[(0,g.jsx)(n,{chip:e??`Блок 3 · Функции и инструменты`,title:`Создаём проект и репозиторий`,intro:`Создадим одно рабочее место для будущего StudyHub: пустой личный remote, его единственный clone и первый запускаемый файл.`}),(0,g.jsxs)(a,{number:`00`,title:`От знакомого файла к своему проекту`,children:[(0,g.jsx)(i,{children:`Мы уже встречали Python-код и запускали его в подготовленной среде. Теперь проверим, что настроенный на компьютере Python 3.12 запускает сохранённый файл, и подготовим папку для дальнейшей работы.`}),(0,g.jsx)(l,{variant:`connected`,items:[{title:`Точка старта`,description:`Есть знакомый файл с print. Проверим локальный Python и подготовим одну папку проекта.`},{title:`Новый вопрос`,description:`Как получить одну собственную папку проекта, связанную с пустым репозиторием в GitHub?`},{title:`Результат`,description:`Один private remote и один clone с сохранённым main.py, правилом для файлов Python и понятным git status. Без commit.`}]}),(0,g.jsx)(`p`,{children:`До сих пор редактор курса давал готовое место для запуска. В этом занятии появляется собственная рабочая папка, а GitHub будет хранить связанный с ней удалённый репозиторий. Сначала мы подготовим эти две стороны, затем создадим файл и проверим его запуск. Проектный код Planner пока не нужен.`}),(0,g.jsx)(`p`,{children:`Перед проектом откройте в VS Code знакомый файл из занятия 12 и запустите его кнопкой Run Python File in Terminal. Сохраните полный путь к выбранному python.exe из команды запуска; если там только python, проверьте его командой Get-Command python и сверьте с Python 3.12 в VS Code. Короткое имя может показать другую версию или не найти программу, это не означает, что выбранный Python 3.12 отсутствует. В таком случае возьмите путь выбранного интерпретатора из списка Python: Select Interpreter, задайте переменную $pythonExe этим путём и проверьте командой & $pythonExe --version. Продолжайте, когда именно этот исполняемый файл показывает Python 3.12.`})]}),(0,g.jsxs)(a,{number:`01`,title:`Файл, Git и GitHub выполняют разные роли`,children:[(0,g.jsx)(i,{children:`Сначала различим место, где лежит рабочий файл, локальную историю изменений и удалённый репозиторий.`}),(0,g.jsx)(`p`,{children:`VS Code помогает открыть и изменить текст. Когда мы нажимаем Save, редактор записывает текущий текст в файл на компьютере. Git работает с папкой проекта и может хранить последовательность сохранённых версий. GitHub размещает удалённый репозиторий, доступный через интернет. Это связанные инструменты, но один не заменяет другой: запись файла не создаёт запись в истории, а наличие страницы на GitHub не означает, что файл уже находится в локальной папке.`}),(0,g.jsx)(`p`,{children:`Репозиторий включает рабочие файлы и сведения об истории. У GitHub будет удалённая сторона, которую называют remote. На компьютере находится её локальный clone. Команда clone получает файлы и историю, если они уже есть, и сохраняет адрес remote под локальным именем origin. Так Git понимает, с каким адресом связана эта папка. Само имя origin является обычной меткой по умолчанию, а не паролем, именем пользователя или доказательством права записи.`}),(0,g.jsx)(`p`,{children:`Представим локальную папку как рабочий стол, а GitHub remote как отдельный шкаф с экземпляром проекта. Clone приносит рабочую копию на стол и записывает, где находится шкаф. После этого изменения на столе сами не переносятся в шкаф. Это сравнение помогает различать места, но clone не является непрерывной синхронизацией или резервным копированием.`}),(0,g.jsx)(`p`,{children:`Важно держать в порядке четыре действия. Save записывает текст файла на диск. Clone получает связанную рабочую копию. Commit в следующем занятии сохранит выбранное состояние в локальной истории Git. Push в занятии 13.1 отправит уже созданный commit на GitHub. Сегодня мы выполняем clone и сохраняем файлы, а commit и push только распознаём как будущие шаги.`}),(0,g.jsx)(p,{prompt:`Соединим каждый инструмент или шаг с его ролью.`,leftTitle:`Инструмент или действие`,rightTitle:`Роль`,pairs:[{left:`VS Code · Save`,right:`Записать текст файла на компьютере`},{left:`Git`,right:`Вести локальную историю проекта`},{left:`GitHub`,right:`Разместить удалённый репозиторий`},{left:`clone`,right:`Получить локальную копию и адрес remote`},{left:`push`,right:`Отправить уже созданный commit`}],explanation:`Мы разделили действия по результату: Save меняет файл, clone получает копию, Git ведёт историю, а push публикует существующий commit.`}),(0,g.jsx)(`p`,{children:`Если всё назвать словом «сохранить», мы потеряем важный выбор: где именно появились данные. После Save текст находится в локальном файле. После clone у нас есть локальная папка и адрес remote. После commit есть новая локальная версия. После push эта версия отправлена на GitHub. Не проверяя место и состояние, нельзя заключить, что файл опубликован.`})]}),(0,g.jsxs)(a,{number:`02`,title:`Создаём пустой private remote и клонируем его один раз`,children:[(0,g.jsx)(i,{children:`Начинаем проект с собственного пустого репозитория. Он будет принадлежать нашей личной учётной записи и станет единственным remote этого учебного проекта.`}),(0,g.jsxs)(`p`,{children:[`Сначала проверим Git. Если Git for Windows ещё не установлен, скачайте установщик с `,(0,g.jsx)(`a`,{href:`https://git-scm.com/install/windows`,children:`официальной страницы Git for Windows`}),`. После установки закройте старые терминалы, затем в VS Code откройте меню Terminal → New Terminal. В PowerShell выполните git --version. Строка git version с номером означает, что Git доступен. Если команда не найдена, перезапустите VS Code и повторите проверку.`]}),(0,g.jsxs)(`p`,{children:[`Теперь настроим вход по HTTPS. Git Credential Manager (GCM) помогает пройти вход GitHub через браузер и безопасно сохранить учётные данные. GCM входит в Git for Windows и предлагается как credential helper по умолчанию; если установщик задаёт вопрос, оставьте Git Credential Manager. Подробнее: `,(0,g.jsx)(`a`,{href:`https://github.com/git-ecosystem/git-credential-manager/blob/main/docs/install.md#windows`,children:`инструкция по установке GCM для Windows`}),`. Пароль и токен не помещают в URL, код или файлы проекта.`]}),(0,g.jsx)(`p`,{children:`На GitHub открываем создание нового репозитория. В поле владельца выбираем свой аккаунт и задаём понятное имя. Видимость выбираем Private. В списке начальных файлов оставляем выключенными README, .gitignore и лицензию. Нам нужен пустой remote, потому что первый исходный файл появится в локальном clone. Если создать README на сайте, удалённая история уже получит начальную запись, а план занятия рассчитывает на пустое начало.`}),(0,g.jsxs)(`figure`,{className:`lesson-infographic`,children:[(0,g.jsx)(`a`,{href:`https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-new-repository`,children:(0,g.jsx)(`img`,{src:`https://docs.github.com/assets/cb-89988/images/help/repository/create-repository-name.png`,alt:`Скриншот из инструкции GitHub: поле имени в форме создания нового репозитория`,style:{aspectRatio:`auto`,objectFit:`contain`}})}),(0,g.jsxs)(`figcaption`,{children:[`Скриншот показывает поле имени. Владельца, Private и выключенные начальные файлы выберите в той же форме. `,(0,g.jsx)(`a`,{href:`https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-new-repository`,children:`Открыть актуальную инструкцию с остальными шагами.`})]})]}),(0,g.jsx)(`p`,{children:`Private означает, что репозиторий доступен владельцу и тем, кому он отдельно дал доступ. Это ограничение доступа, а не шифрование содержимого и не место для секретов. Мы не помещаем пароль, токен или код восстановления ни в команду, ни в Python-файл, ни в .gitignore. Для этого урока достаточно личного репозитория, который текущая учётная запись может читать.`}),(0,g.jsx)(`p`,{children:`HTTPS-ссылка состоит из имени владельца и имени репозитория. Она помогает точно определить remote, но не заменяет учётную запись. Перед копированием адреса сверяем владельца и имя на странице GitHub. Если выбранное имя уже использовано, создаём другое уникальное имя в своём аккаунте, а не подключаемся к чужому или готовому StudyHub. Браузерный вход через GCM подтверждает учётную запись, а успешный clone подтверждает чтение именно выбранного адреса.`}),(0,g.jsx)(`p`,{children:`С GitHub копируем HTTPS-адрес созданного пустого репозитория. При первом обращении к private remote Git может открыть окно браузера через GCM. Входим в тот же аккаунт, который владеет репозиторием, и подтверждаем запрошенную авторизацию. GCM сохраняет учётные данные системным способом; их не нужно вводить в URL или сохранять в проекте. Если вход уже сохранён, окно может не появиться. Успешный clone подтверждает доступ на чтение, но не проверяет, разрешён ли push.`}),(0,g.jsxs)(`p`,{children:[`В `,(0,g.jsx)(`a`,{href:`https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-new-repository`,children:`инструкции GitHub по созданию репозитория`}),` есть снимки остальных полей формы. Расположение элементов может меняться, поэтому сверяйте их названия и выбранные значения.`]}),(0,g.jsx)(c,{question:`Что подтверждает успешный clone private-репозитория?`,options:[`Что будущий push точно разрешён`,`Что текущий вход смог прочитать remote и получить clone`,`Что файл main.py уже создан на компьютере`],correctIndex:1,explanation:`Clone проверяет чтение и создаёт связанную локальную копию. Право push и создание main.py относятся к другим шагам.`}),(0,g.jsx)(`p`,{children:`Если учётная запись не видит private-репозиторий, проверяем владельца и скопированный HTTPS-адрес. Если браузерный вход недоступен, нет сети или Git нельзя установить, это внешний блокер. Не меняем private на public ради обхода и не просим учеников вставлять токены в команды. Сначала устраняем причину штатным способом или останавливаем зависимую часть.`})]}),(0,g.jsxs)(a,{number:`03`,title:`Один clone, правильная папка и адрес origin`,children:[(0,g.jsx)(i,{children:`Перед clone проверим путь назначения, чтобы не создать второй проект внутри случайно выбранной папки.`}),(0,g.jsx)(`p`,{children:`Терминал выполняет команды относительно текущей папки. Поэтому сначала читаем её путь командой Get-Location и при необходимости смотрим содержимое через Get-ChildItem. Если будущая папка проекта не существует, clone создаст её по имени репозитория. Если выбранная папка уже существует и пуста, используем её как согласованное место назначения, не создавая внутри ещё один clone.`}),(0,g.jsx)(`p`,{children:`Если в папке уже лежит правильный clone и его origin ведёт на созданный remote, открываем и продолжаем эту копию. Если clone прервался, содержимое неожиданное или адрес непонятен, ничего не удаляем. Проверяем состояние, затем выбираем отдельную свободную соседнюю папку либо останавливаем этот шаг. Удаление файлов не является способом исправить сомнение в пути.`}),(0,g.jsx)(`p`,{children:`Имя папки и имя remote могут отличаться, потому что clone позволяет выбрать отдельную целевую папку. В этом занятии удобнее оставить стандартное имя, чтобы путь было легко сопоставить с URL. Сам факт, что папка существует, не доказывает, что она подходит: там могут быть личные файлы, другой проект или незавершённый clone. Мы различаем отсутствующую, пустую, правильную и неизвестную папку. В неизвестную папку не записываем; правильный clone открываем повторно.`}),(0,g.jsx)(`p`,{children:`Когда папка назначения проверена, скопируйте HTTPS URL со страницы своего репозитория. В шаблоне замените OWNER на имя владельца GitHub, а REPOSITORY на имя репозитория. Вместо ручной подстановки можно целиком скопировать URL кнопкой Code на странице.`}),(0,g.jsx)(h,{caption:`PowerShell · клонировать пустой remote`,code:`git clone https://github.com/OWNER/REPOSITORY.git
Set-Location REPOSITORY
git remote -v`}),(0,g.jsx)(`p`,{children:`При успешном клонировании пустого remote Git сообщает, что репозиторий пуст. Это ожидаемое сообщение: локальная папка создана, в ней пока нет файлов из истории.`}),(0,g.jsx)(h,{caption:`Ожидаемое предупреждение после clone пустого репозитория`,code:`Cloning into 'REPOSITORY'...
warning: You appear to have cloned an empty repository.`}),(0,g.jsx)(h,{caption:`Пример вывода git remote -v`,code:`origin  https://github.com/OWNER/REPOSITORY.git (fetch)
origin  https://github.com/OWNER/REPOSITORY.git (push)`}),(0,g.jsx)(`p`,{children:`Для origin одинаковый URL показан в двух строках: fetch для чтения и push для отправки. Это адрес удалённого репозитория, а не проверка права push.`}),(0,g.jsx)(`p`,{children:`Имя origin можно сравнить с именем контакта в адресной книге: по короткой метке Git находит сохранённый адрес. Clone подтверждает чтение private remote; право отправлять изменения проверяется отдельно в последующих занятиях.`}),(0,g.jsx)(m,{caption:`Как пустой remote превращается в рабочую папку`,orientation:`vertical`,children:(0,g.jsxs)(f,{label:`От GitHub remote к локальным файлам и чтению состояния`,orientation:`vertical`,children:[(0,g.jsx)(u,{title:`GitHub · private remote`,children:(0,g.jsx)(`p`,{children:`Пустой репозиторий в личном аккаунте`})}),(0,g.jsx)(d,{label:`git clone по HTTPS, сохраняется origin`}),(0,g.jsx)(u,{title:`Локальный clone`,children:(0,g.jsx)(`p`,{children:`Одна папка проекта, связанная с адресом remote`})}),(0,g.jsx)(d,{label:`VS Code сохраняет файлы сюда`}),(0,g.jsx)(u,{title:`Рабочая папка`,children:(0,g.jsx)(`p`,{children:`main.py и .gitignore находятся в корне clone`})}),(0,g.jsx)(d,{label:`git status читает состояние`}),(0,g.jsx)(u,{title:`Незакоммиченные файлы`,children:(0,g.jsx)(`p`,{children:`Git сообщает, что оба файла ещё не в истории`})})]})}),(0,g.jsx)(`p`,{children:`Читаем схему сверху вниз: сначала появляется clone, затем VS Code сохраняет в него файлы, а git status показывает их состояние.`}),(0,g.jsx)(`p`,{children:`При ошибке «repository not found» сверьте URL, владельца и аккаунт с доступом на чтение. Clone должен указывать на созданный вами пустой remote.`})]}),(0,g.jsxs)(a,{number:`04`,title:`Создаём и запускаем сохранённый main.py`,children:[(0,g.jsx)(i,{children:`Первый файл находится в корне clone. В нём пока только знакомая команда, которая показывает короткое приветствие.`}),(0,g.jsx)(`p`,{children:`Открываем в VS Code именно папку clone, а не родительскую папку и не другой проект с таким же именем. В панели файлов создаём main.py на верхнем уровне проекта. Расширение .py является частью имени: оно показывает, что это исходный файл Python. Открытая вкладка сама по себе не доказывает, где лежит файл, поэтому проверяем путь в заголовке редактора и в панели Explorer.`}),(0,g.jsx)(`p`,{children:`В редакторе VS Code, в файле main.py, записываем одну знакомую строку: print("Hello world"). После Save запускаем именно сохранённый вариант. Если вкладка отмечена как несохранённая, сначала сохраните её.`}),(0,g.jsx)(`p`,{children:`На маленьком примере сначала предскажем результат. Кавычки отмечают текст в исходном коде; сами кавычки программа не печатает. В терминале после запуска появится строка Hello world. Карточка ниже показывает ожидаемый вывод, она не запускает файл вместо нас.`}),(0,g.jsx)(s,{code:`print("Hello world")`,output:`Hello world`,hint:`Посмотри, какой текст находится между кавычками, и что именно передано в print.`}),(0,g.jsx)(`p`,{children:`После разобранного примера меняем только слова приветствия. До запуска предсказываем новую строку, сохраняем файл и проверяем, что вывод изменился. Затем возвращаем Hello world, снова сохраняем и запускаем. Так мы убеждаемся, что работаем с нужной копией и оставляем в проекте ровно тот результат, который предусмотрен планом.`}),(0,g.jsx)(`p`,{children:`У файла с тем же именем в другой папке может быть другое содержимое. Если в терминале отображается прежнее приветствие или Python сообщает, что файл не найден, сверяем три вещи: открытую папку VS Code, путь текущей папки терминала и сохранение вкладки. Не создаём второй main.py для обхода ошибки и не перемещаем файл в случайный каталог.`}),(0,g.jsx)(`p`,{children:`После запуска main.py остаётся первым исходным файлом проекта. В следующем разделе подготовим корневой .gitignore для Python-артефактов.`})]}),(0,g.jsxs)(a,{number:`05`,title:`Выбираем Python 3.12 и понимаем приглашение терминала`,children:[(0,g.jsx)(i,{children:`Файл хранится в clone, а выполняет его выбранный установленный Python. Команда должна запускаться из папки, где находится main.py.`}),(0,g.jsx)(`p`,{children:`VS Code является редактором, расширение Microsoft Python помогает выбирать интерпретатор и запускать файл, но сам текст выполняет Python. В занятии 12 мы проверяли выбранную версию и запуск знакомого файла. Перед работой с проектом сверяем, что выбран именно системный Python 3.12, а не случайная другая установка. Отдельное виртуальное окружение и сторонние пакеты этой главе не нужны.`}),(0,g.jsx)(`p`,{children:`Кнопка Run Python File in Terminal запускает открытый файл выбранным интерпретатором. Если вводите команды вручную, делайте это в PowerShell из корня clone. Используйте короткое имя python, только если python --version показывает 3.12. Если команда отсутствует или ведёт к другой версии, присвойте $pythonExe полный путь выбранного python.exe и вызовите его через оператор &. В примере ниже путь учебный: замени его своим.`}),(0,g.jsx)(h,{caption:`PowerShell · выбери один способ: короткое имя или проверенный полный путь`,code:_}),(0,g.jsxs)(`p`,{children:[`Внизу VS Code обычно открыта оболочка PowerShell. Её приглашение начинается с PS и показывает путь. В PowerShell мы вводим команды вроде python main.py, git clone или git status. Приглашение `,`>>>`,` означает, что сейчас открыт интерактивный Python; туда вводят выражения и команды Python, но не команды PowerShell. Один и тот же экран терминала может переключаться между этими режимами, поэтому смотрим на приглашение до ввода.`]}),(0,g.jsx)(`p`,{children:`У текущей папки есть практический смысл. Короткое имя main.py ищется относительно неё. Если терминал открыт уровнем выше или в соседнем проекте, команда запуска может не найти файл либо обратиться к другой копии. Сначала читаем путь, затем убеждаемся, что в VS Code открыт этот же clone, и только после этого запускаем.`}),(0,g.jsxs)(`p`,{children:[`Если короткое имя запускает не 3.12, выберите Python 3.12 в VS Code и вызовите его по проверенному пути через & $pythonExe. Если файл не найден, проверьте папку и имя main.py. При приглашении `,`>>>`,` выполните exit(), чтобы вернуться из интерактивного Python в PowerShell.`]}),(0,g.jsx)(o,{statement:(0,g.jsx)(g.Fragment,{children:`Если в PowerShell мы запустили main.py из папки clone проверенным Python 3.12, интерпретатор выполняет сохранённый файл по этому пути.`}),isTrue:!0,explanation:`Короткое имя файла разрешается от текущей папки. Поэтому сначала сверяем путь clone и сохранение main.py.`}),(0,g.jsx)(`p`,{children:`В терминале после запуска виден вывод процесса. Если код был изменён в редакторе, сначала сохраняем изменения, иначе проверяем не последнюю версию. Когда вывод совпадает с ожидаемым, наш локальный Python и файл связаны правильно. Это наблюдение пригодится после добавления .gitignore, когда мы повторим запуск ещё раз.`})]}),(0,g.jsxs)(a,{number:`06`,title:`Добавляем .gitignore и читаем git status`,children:[(0,g.jsx)(i,{children:`Перед тем как Git будет предлагать добавить файлы в историю, укажем, какие обычные артефакты Python не относятся к исходникам.`}),(0,g.jsx)(`p`,{children:`Python может создавать папки __pycache__/ и файлы с окончанием .pyc при работе с модулями. Это технические файлы, а не исходный текст нашего проекта. Сейчас не изучаем устройство кэша или import. Нам достаточно распознать два вида артефактов и указать Git, что такие пути не следует предлагать как обычные новые файлы.`}),(0,g.jsx)(`p`,{children:`В корне clone создаём обычный текстовый файл с точным именем .gitignore. В него записываем две отдельные строки: __pycache__/ и *.pyc. Первая строка задаёт папки с таким именем, вторая подходит файлам с расширением .pyc. Мы используем только эти два правила, потому что в этой главе запускаем системный Python и не создаём .venv.`}),(0,g.jsx)(h,{caption:`Две строки в корневом .gitignore`,code:`__pycache__/
*.pyc`}),(0,g.jsx)(`p`,{children:`Сравним правило с отметкой на коробке: оно сообщает Git, какие пути не показывать среди обычных кандидатов для будущего включения. Файл при этом остаётся на компьютере, а правило не очищает уже отслеживаемый путь. Это не кнопка удаления, не защита секрета и не команда commit. Если токен или пароль уже сохранён в обычном файле, .gitignore не делает его безопасным.`}),(0,g.jsx)(`p`,{children:`Игнорирование также не означает, что файл исчезает из VS Code или проводника. Правило влияет на то, как Git показывает подходящие новые пути. Если файл уже попал в историю, добавление строки в .gitignore само по себе не прекращает отслеживание. Поэтому мы вообще не сохраняем секреты в проекте и не используем ignore как замену осторожной проверке содержимого.`}),(0,g.jsx)(`p`,{children:`Теперь читаем git status. Команда показывает состояние файлов и истории в текущей папке, но сама ничего не изменяет. В пустом clone мы можем увидеть сообщение, что commit ещё нет, а main.py и .gitignore перечислены как новые, то есть неотслеживаемые файлы. Если появятся совпадающие с правилами Python-артефакты, обычный статус их не перечислит. Это не значит, что они удалены.`}),(0,g.jsx)(`p`,{children:`Обычный git diff не показывает содержимое новых неотслеживаемых файлов. Сверьте текст в VS Code, затем прочитайте git status.`}),(0,g.jsx)(`p`,{children:`Сохраняем .gitignore и запускаем main.py ещё раз. Это последняя правка проектных файлов и последняя проверка прежней возможности. В конце мы можем показать два файла в корне, запустить приветствие и объяснить, почему status сообщает о новых файлах, хотя commit ещё нет.`}),(0,g.jsx)(o,{statement:(0,g.jsx)(g.Fragment,{children:`Файл, подходящий под правило .gitignore, удаляется с компьютера и исчезает из VS Code.`}),isTrue:!1,explanation:`Правило влияет на то, как Git учитывает путь. Сам файл остаётся на диске и виден в редакторе.`}),(0,g.jsx)(o,{statement:(0,g.jsx)(g.Fragment,{children:`git status создаёт commit, когда показывает main.py и .gitignore как новые файлы.`}),isTrue:!1,explanation:`status только читает состояние. Локальный commit будет отдельной темой занятия 13.`}),(0,g.jsx)(`p`,{children:`Таким образом, в конце урока есть один личный пустой remote и связанный с ним clone. Внутри clone сохранены main.py с Hello world и корневой .gitignore с двумя правилами. Мы проверили запуск выбранным Python 3.12 и поняли состояние файлов. Push-доступ не проверяли, файлы пока не staged и не закоммичены.`})]}),(0,g.jsxs)(a,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,g.jsx)(i,{children:`Практика соединяет объяснённые действия в одном собственном проекте. До clone мы проверяем доступность инструментов и точный путь назначения.`}),(0,g.jsx)(l,{variant:`connected`,items:[{title:`Пустой remote и один clone`,description:`Создадим пустой private remote, скопируем его HTTPS-адрес и получим один clone. Локальная папка будет связана с нужным origin, а текущая учётная запись сможет читать репозиторий.`},{title:`Сохранённый main.py`,description:`В корне clone сохраним main.py, запустим его выбранным Python 3.12, изменим и вернём приветствие. Сохранённый файл выведет Hello world из правильной папки.`},{title:`.gitignore и состояние`,description:`Добавим две строки в .gitignore, повторно запустим main.py и прочитаем git status. В одном clone будут нужные файлы, понятное состояние и ещё ни одного изменения в истории.`}]}),(0,g.jsx)(`p`,{children:`Если установка, вход или сеть блокируют шаг, запишите точное сообщение и продолжите после устранения причины. В итоге один clone связан с нужным origin, а в нём сохранены запускаемый main.py и корневой .gitignore.`}),(0,g.jsx)(t,{points:[(0,g.jsx)(g.Fragment,{children:`Save меняет файл, clone получает связанную копию, commit сохраняет локальную версию, push отправляет готовый commit.`}),(0,g.jsx)(g.Fragment,{children:`Все проектные файлы находятся в одном clone; адрес remote сверяется через origin.`}),(0,g.jsx)(g.Fragment,{children:`Корневой .gitignore содержит только __pycache__/ и *.pyc; git status только читает состояние.`}),(0,g.jsx)(g.Fragment,{children:`Передача дальше: сохранённый и запускаемый main.py, правила игнорирования и рабочая копия без commit.`})]})]})]})}export{v as Lesson12_1};